"""Thumbnail cache outside the repo: `<cache_dir>/<thumb_key>.jpg`, generated by a small worker pool."""
from __future__ import annotations

import itertools
import os
import queue
import threading
from collections import OrderedDict
from pathlib import Path
from typing import Iterable

from ..errors import InvalidImage
from ..ports import ImageTool
from .thumb_key import thumb_key

PREFETCH_PRIORITY = 10
FAILED_MAX = 10_000
GET_TIMEOUT = 60.0


class _Job:
    __slots__ = ("key", "path", "priority", "done", "error", "started")

    def __init__(self, key: str, path: Path, priority: int) -> None:
        self.key, self.path, self.priority = key, path, priority
        self.done = threading.Event()
        self.error: str | None = None
        self.started = False


class ThumbPool:
    def __init__(self, cache_dir: Path, tool: ImageTool, workers: int | None = None,
                 width: int = 360, quality: int = 82) -> None:
        self.cache_dir, self.tool, self.width, self.quality = Path(cache_dir), tool, width, quality
        n = workers if workers is not None else min(4, max(2, (os.cpu_count() or 2) // 2))
        self._queue: queue.PriorityQueue = queue.PriorityQueue()
        self._seq = itertools.count()
        self._lock = threading.Lock()
        self._jobs: dict[str, _Job] = {}
        self._closed = False
        self._failed: OrderedDict[str, None] = OrderedDict()  # keys that failed; prefetch skips them
        self.timeout = GET_TIMEOUT
        self._sweep()
        self._threads = [threading.Thread(target=self._work, name=f"thumb-{i}", daemon=True) for i in range(n)]
        for t in self._threads:
            t.start()

    def _sweep(self) -> None:
        """Remove temp files left by a previous run."""
        if self.cache_dir.is_dir():
            for pat in ("*.part", "*.part.jpg"):
                for f in self.cache_dir.glob(pat):
                    f.unlink(missing_ok=True)

    def key(self, path: Path) -> str:
        return thumb_key(path, path.stat())

    def _cached(self, key: str) -> Path:
        return self.cache_dir / f"{key}.jpg"

    def _submit(self, path: Path, priority: int, retry: bool, key: str | None = None) -> tuple[str, _Job | None]:
        """Enqueue (single-flight per key); job is None when already cached or (prefetch) known-bad."""
        key = key or self.key(path)
        with self._lock:
            if self._closed:
                raise InvalidImage("thumbnail pool is closed")
            if self._cached(key).exists() or (not retry and key in self._failed):
                return key, None
            job = self._jobs.get(key)
            if job is None:
                job = self._jobs[key] = _Job(key, path, priority)
            elif priority >= job.priority or job.started:
                return key, job
            else:
                job.priority = priority  # promote: a duplicate queue entry; the stale one is skipped
            self._queue.put((priority, next(self._seq), job))
            return key, job

    def get(self, path: Path, priority: int = 0) -> Path:
        key, job = self._submit(path, priority, retry=True)
        if job is not None and not job.done.wait(self.timeout):
            raise InvalidImage(f"thumbnail of {path.name} timed out")
        out = self._cached(key)
        if job is not None and (job.error is not None or not out.exists()):
            raise InvalidImage(job.error or f"thumbnail of {path.name} failed")
        return out

    def prefetch(self, paths: Iterable[Path]) -> None:
        for p in paths:
            try:
                self._submit(p, PREFETCH_PRIORITY, retry=False)
            except (OSError, InvalidImage):
                pass

    def prefetch_keyed(self, items: Iterable[tuple[str, Path]]) -> None:
        """prefetch() of (key, path) pairs whose key the caller already knows (from the library index): no stat."""
        for key, p in items:
            try:
                self._submit(p, PREFETCH_PRIORITY, retry=False, key=key)
            except (OSError, InvalidImage):
                pass

    def close(self) -> None:
        with self._lock:
            if self._closed:
                return
            self._closed = True
            while True:  # drain the backlog and wake every waiter
                try:
                    _, _, job = self._queue.get_nowait()
                except queue.Empty:
                    break
                if job is not None and not job.started:
                    job.error = "closed"
                    self._jobs.pop(job.key, None)
                    job.done.set()
        for _ in self._threads:
            self._queue.put((-1, next(self._seq), None))
        for t in self._threads:
            t.join(timeout=5)

    def _work(self) -> None:
        while True:
            try:
                _, _, job = self._queue.get()
                if job is None:
                    return
                with self._lock:
                    if job.started or job.done.is_set():
                        continue  # stale duplicate of a promoted job
                    job.started = True
                try:
                    self._generate(job)
                finally:
                    with self._lock:
                        self._jobs.pop(job.key, None)
                        if job.error is not None:
                            self._failed[job.key] = None
                            while len(self._failed) > FAILED_MAX:
                                self._failed.popitem(last=False)
                        else:
                            self._failed.pop(job.key, None)
                    job.done.set()
            except BaseException:  # noqa: BLE001 - a worker never dies
                continue

    def _generate(self, job: _Job) -> None:
        out = self._cached(job.key)
        tmp = self.cache_dir / f"{job.key}.{threading.get_ident()}.part"
        try:
            self.cache_dir.mkdir(parents=True, exist_ok=True)
            self.tool.thumbnail(job.path, tmp, self.width, self.quality)
            os.replace(tmp, out)
        except Exception as e:  # noqa: BLE001 - any failure is reported to waiters, never cached as a file
            job.error = str(e) or type(e).__name__
        finally:
            try:
                tmp.unlink(missing_ok=True)
            except OSError:
                pass
